import { existsSync, readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";

/**
 * package.json is regenerated by Speakeasy; the subpath exports of the
 * hand-written code are persistent edits kept by its three-way merge. This
 * fails if a regeneration drops one of them, which nothing else would notice
 * since the tests import from src/.
 */
const packageRoot = new URL("../", import.meta.url);
const packageJson = JSON.parse(
  readFileSync(new URL("package.json", packageRoot), "utf-8"),
);

const HAND_WRITTEN_EXPORTS = [
  "./extra/realtime",
  "./extra/observability",
  "./extra/connectors",
  "./extra/workflows",
  "./hooks/tracing",
];

describe("package.json exports", () => {
  it.each(HAND_WRITTEN_EXPORTS)("exports %s from an existing source", (path) => {
    const entry = packageJson.exports[path];

    expect(entry).toBeDefined();
    expect(existsSync(new URL(entry.source, packageRoot))).toBe(true);
  });
});
